// Helper function to count integers in the list
function CountInt(values: seq<object>): int
    ensures CountInt(values) >= 0
    ensures CountInt(values) <= |values|
{
    var count := 0;
    var i := 0;
    while i < |values|
        invariant 0 <= count <= i
        invariant count == CountInt(subseq(values, 0, i))
    {
        if values[i] is int {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
